contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint16 newFeeRate) public {
        require(!c.initialized());
        c.setFeeRate(newFeeRate); if (__ESBMC_reverted()) return;
        assert(!c.initialized());
    }

    receive() external payable {}
}

