// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint16 newFeeRate) internal {
        vm.assume(!c.initialized());
        try c.setFeeRate(newFeeRate) {} catch { return; }
        assertTrue(!c.initialized());
    }

    function testFuzz_run(uint16 newFeeRate) public {
        _run(newFeeRate);
    }

    receive() external payable {}
}
